// Commit heatmap + drill-down. Data comes from activity-data.js (monthly counts, loaded with
// the page) and commits.js (per-commit details, loaded on the first click). Both files are
// generated by tools/gen_history.py.
//
// [data-activity="all"]  repo × month grid with era brackets
// [data-activity="<key>"] one repo's strip; add data-compact to drop the legend/table view
// Clicking a cell opens that month's commits grouped by day; clicking a commit shows its
// description, the areas it touched (+/− lines) and the GitHub link.
(function () {
  var A = window.ACTIVITY;
  var hosts = document.querySelectorAll('[data-activity]');
  if (!A || !hosts.length) { return; }

  var NS = 'http://www.w3.org/2000/svg';
  var LOWER = [0, 1, 3, 6, 11, 21];
  var FILL = ['#efefef', '#d0d0d0', '#a0a0a0', '#6b6b6b', '#3b3b3b', '#111111'];
  var RANGE = ['0', '1–2', '3–5', '6–10', '11–20', '21+'];
  var WEEK = ['일', '월', '화', '수', '목', '금', '토'];
  var COUNT = A.repos[0].counts.length;
  var BASE = A.start[0] * 12 + (A.start[1] - 1);
  var REPO = {};
  A.repos.forEach(function (r) { REPO[r.key] = r; });
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function monthKey(i) {
    var t = BASE + i, m = t % 12 + 1;
    return Math.floor(t / 12) + '-' + (m < 10 ? '0' : '') + m;
  }
  function monthLabel(i) { return monthKey(i).replace('-', '.'); }
  function indexOf(ym) {
    var p = ym.split('-');
    return (+p[0] * 12 + (+p[1] - 1)) - BASE;
  }
  function level(n) {
    for (var i = LOWER.length - 1; i > 0; i--) { if (n >= LOWER[i]) { return i; } }
    return 0;
  }
  function svgNode(name, attrs, parent) {
    var e = document.createElementNS(NS, name);
    for (var k in attrs) { e.setAttribute(k, attrs[k]); }
    if (parent) { parent.appendChild(e); }
    return e;
  }
  function svgText(parent, x, y, cls, str, anchor) {
    var t = svgNode('text', { x: x, y: y, 'class': cls }, parent);
    if (anchor) { t.setAttribute('text-anchor', anchor); }
    t.textContent = str;
    return t;
  }
  function el(name, cls, str, parent) {
    var e = document.createElement(name);
    if (cls) { e.className = cls; }
    if (str !== undefined && str !== null) { e.textContent = str; }
    if (parent) { parent.appendChild(e); }
    return e;
  }
  function sum(arr) { return arr.reduce(function (a, b) { return a + b; }, 0); }
  function plural(n, unit) { return n + unit; }

  // commits.js is ~120KB, so it is only pulled in when someone actually drills down.
  var pending = null;
  function withCommits(done, fail) {
    if (window.COMMITS) { done(window.COMMITS); return; }
    if (!pending) {
      pending = [];
      var s = document.createElement('script');
      s.src = 'commits.js';
      s.onload = function () { flush(true); };
      s.onerror = function () { s.remove(); flush(false); };
      document.head.appendChild(s);
    }
    pending.push([done, fail]);
    function flush(ok) {
      var q = pending; pending = null;
      q.forEach(function (w) { if (ok && window.COMMITS) { w[0](window.COMMITS); } else { w[1](); } });
    }
  }

  hosts.forEach(function (host) {
    var key = host.getAttribute('data-activity');
    var all = key === 'all';
    var compact = host.hasAttribute('data-compact');
    var rows = all ? A.repos : A.repos.filter(function (r) { return r.key === key; });
    if (!rows.length) { return; }

    var LW = all ? 104 : 16, CELL = 15, STEP = 18;
    var top = all ? 48 : 24;
    var W = LW + COUNT * STEP;
    var H = top + rows.length * STEP;

    host.textContent = '';
    host.classList.add('hm');
    if (!all) { host.classList.add('single'); }
    if (compact) { host.classList.add('compact'); }

    var scroll = el('div', 'hm-scroll', null, host);
    var svg = svgNode('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' }, scroll);
    svg.setAttribute('aria-label', (all ? '저장소 ' + rows.length + '개의' : rows[0].name + ' 저장소의') + ' 월별 커밋 수, ' +
      monthLabel(0) + '부터 ' + monthLabel(COUNT - 1) + '까지. 칸을 누르면 그 달의 커밋 목록이 열림.');

    for (var i = 0; i < COUNT; i++) {
      var t = BASE + i;
      if (i === 0 || t % 12 === 0) {
        var x = LW + i * STEP;
        svgText(svg, x, top - 9, 'yr mono', String(Math.floor(t / 12)));
        if (i > 0) { svgNode('line', { x1: x - 1.5, x2: x - 1.5, y1: top - 20, y2: H, 'class': 'ysep' }, svg); }
      }
    }
    if (all) {
      A.eras.forEach(function (e) {
        var x1 = LW + indexOf(e.from) * STEP, x2 = LW + indexOf(e.to) * STEP + CELL;
        svgNode('path', { d: 'M' + x1 + ',18V12H' + x2 + 'V18', 'class': 'era-line' }, svg);
        svgText(svg, x1, 8, 'era-n mono', e.n);
      });
    }

    var cells = {};
    rows.forEach(function (r, ri) {
      var y = top + ri * STEP;
      if (all) {
        var link = svgNode('a', { href: r.href }, svg);
        if (r.href.indexOf('http') === 0) { link.setAttribute('target', '_blank'); link.setAttribute('rel', 'noopener'); }
        svgText(link, 0, y + 12, 'rowlbl', r.name);
      }
      cells[r.key] = r.counts.map(function (n, ci) {
        return svgNode('rect', {
          x: LW + ci * STEP, y: y, width: CELL, height: CELL, rx: 2,
          fill: FILL[level(n)], 'class': 'cell' + (n ? ' has' : ''),
          'data-n': n, 'data-i': ci, 'data-k': r.key
        }, svg);
      });
    });

    // hover tooltip — value first, then repo · month
    var tip = el('div', 'hm-tip', null, host);
    var tipValue = el('b', '', '', tip);
    var tipLabel = el('span', '', '', tip);
    var tipHint = el('em', '', '', tip);
    var hot = null;
    function cellOf(target) {
      return target && target.classList && target.classList.contains('cell') ? target : null;
    }
    svg.addEventListener('pointerover', function (ev) {
      var c = cellOf(ev.target);
      if (!c) { return; }
      if (hot) { hot.classList.remove('hot'); }
      hot = c; c.classList.add('hot');
      var n = +c.getAttribute('data-n');
      tipValue.textContent = '커밋 ' + n + '개';
      tipLabel.textContent = REPO[c.getAttribute('data-k')].name + ' · ' + monthLabel(+c.getAttribute('data-i'));
      tipHint.textContent = n ? '클릭하면 날짜별 커밋' : '';
      var hr = host.getBoundingClientRect(), cr = c.getBoundingClientRect();
      var half = tip.offsetWidth / 2;
      var left = Math.min(Math.max(cr.left + cr.width / 2 - hr.left, half), hr.width - half);
      tip.style.left = left + 'px';
      tip.style.top = (cr.top - hr.top) + 'px';
      tip.classList.add('show');
    });
    svg.addEventListener('pointerleave', function () {
      tip.classList.remove('show');
      if (hot) { hot.classList.remove('hot'); hot = null; }
    });

    // legend + totals
    var foot = el('div', 'hm-foot', null, host);
    if (!compact) {
      var legend = el('div', 'hm-legend mono', null, foot);
      el('span', '', '월별 커밋', legend);
      FILL.forEach(function (f, li) {
        var sw = el('i', '', null, legend);
        sw.style.background = f;
        sw.title = RANGE[li];
      });
      el('span', '', '0 → 21+', legend);
    }
    var total = sum(rows.map(function (r) { return sum(r.counts); }));
    var active = 0;
    for (var mi = 0; mi < COUNT; mi++) {
      if (rows.some(function (r) { return r.counts[mi] > 0; })) { active++; }
    }
    el('span', 'mono', (all ? '저장소 ' + rows.length + '개 · ' : '') + '커밋 ' + total + '개 · 활동한 달 ' + active + '개 · ' +
      A.asOf + ' 기준' + (compact ? '' : ', 머지 커밋 제외') + ' · 칸을 누르면 커밋 목록', foot);

    // ---------------- drill-down panel ----------------
    var panel = null;
    var state = null;          // { i: month index, k: repo key or null for every repo }

    function markSelection() {
      Object.keys(cells).forEach(function (k) {
        cells[k].forEach(function (c, ci) {
          var on = state && ci === state.i && (state.k === null || state.k === k);
          c.classList.toggle('sel', !!on);
        });
      });
    }

    function close() {
      if (!panel) { return; }
      panel.remove();
      panel = null; state = null;
      markSelection();
    }

    function open(i, k) {
      state = { i: i, k: k };
      markSelection();
      if (!panel) {
        panel = el('div', 'hm-panel');
        panel.setAttribute('role', 'region');
        host.insertBefore(panel, foot.nextSibling);
        panel.addEventListener('keydown', function (ev) { if (ev.key === 'Escape') { close(); } });
      }
      panel.textContent = '';
      panel.setAttribute('aria-label', monthLabel(i) + ' 커밋 목록');
      var head = el('div', 'hp-head', null, panel);
      var title = el('div', 'hp-title', null, head);
      el('b', '', monthLabel(i), title);
      var subtitle = el('span', '', '불러오는 중…', title);
      var x = el('button', 'hp-close', '×', head);
      x.type = 'button';
      x.setAttribute('aria-label', '커밋 목록 닫기');
      x.addEventListener('click', close);
      withCommits(function (C) { render(C, i, k, subtitle); }, function () {
        subtitle.textContent = '커밋 데이터를 못 불러옴 — 새로고침 후 다시 시도';
      });
      panel.scrollIntoView({ block: 'nearest', behavior: reduceMotion ? 'auto' : 'smooth' });
    }

    function render(C, i, k, subtitle) {
      if (!panel || !state || state.i !== i || state.k !== k) { return; }
      var ym = monthKey(i);
      var keys = rows.map(function (r) { return r.key; });
      var byRepo = {};
      keys.forEach(function (rk) {
        byRepo[rk] = (C[rk] || []).filter(function (c) { return c.t.slice(0, 7) === ym; });
      });
      var shown = k === null ? keys : [k];
      var list = [];
      shown.forEach(function (rk) { byRepo[rk].forEach(function (c) { list.push({ c: c, k: rk }); }); });
      list.sort(function (a, b) { return a.c.t < b.c.t ? -1 : a.c.t > b.c.t ? 1 : 0; });

      var repoCount = shown.filter(function (rk) { return byRepo[rk].length; }).length;
      subtitle.textContent = (k === null ? (all ? '저장소 ' + repoCount + '개 · ' : '') : REPO[k].name + ' · ') +
        '커밋 ' + list.length + '개' + (list.length ? ' — 커밋을 누르면 변경 내용' : '');

      if (all) {
        var chips = el('div', 'hp-chips', null, panel);
        var monthTotal = sum(keys.map(function (rk) { return byRepo[rk].length; }));
        addChip(chips, '전체', monthTotal, k === null, function () { open(i, null); });
        keys.forEach(function (rk) {
          if (!byRepo[rk].length) { return; }
          addChip(chips, REPO[rk].name, byRepo[rk].length, k === rk, function () { open(i, rk); });
        });
      }

      var body = el('div', 'hp-body', null, panel);
      if (!list.length) {
        el('p', 'hp-empty', '이 달엔 커밋이 없음.', body);
        return;
      }
      var day = null;
      list.forEach(function (item) {
        var d = item.c.t.slice(0, 10);
        if (d !== day) {
          day = d;
          var p = d.split('-');
          var wd = WEEK[new Date(+p[0], +p[1] - 1, +p[2]).getDay()];
          var n = list.filter(function (o) { return o.c.t.slice(0, 10) === d; }).length;
          var dh = el('div', 'hp-day', null, body);
          el('b', 'mono', p[1] + '.' + p[2] + ' ' + wd, dh);
          el('span', '', plural(n, '개'), dh);
        }
        commitRow(body, item.c, item.k, k === null && all);
      });
    }

    function addChip(parent, label, n, on, onClick) {
      var b = el('button', 'hp-chip' + (on ? ' on' : ''), null, parent);
      b.type = 'button';
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
      el('span', '', label, b);
      el('span', 'n mono', String(n), b);
      b.addEventListener('click', onClick);
    }

    function commitRow(parent, c, rk, showRepo) {
      var wrap = el('div', 'cm', null, parent);
      var row = el('button', 'cm-row' + (showRepo ? ' multi' : ''), null, wrap);
      row.type = 'button';
      row.setAttribute('aria-expanded', 'false');
      el('span', 'cm-time mono', c.t.slice(11), row);
      if (showRepo) { el('span', 'cm-repo', REPO[rk].name, row); }
      el('span', 'cm-title', c.m, row);
      var add = sum(c.a.map(function (a) { return a[1]; })), del = sum(c.a.map(function (a) { return a[2]; }));
      el('span', 'cm-stat mono', '+' + add + ' −' + del, row);
      var detail = null;
      row.addEventListener('click', function () {
        var openNow = row.getAttribute('aria-expanded') !== 'true';
        row.setAttribute('aria-expanded', openNow ? 'true' : 'false');
        if (!detail) { detail = commitDetail(wrap, c, rk); }
        detail.hidden = !openNow;
      });
    }

    function commitDetail(parent, c, rk) {
      var d = el('div', 'cm-detail', null, parent);
      if (c.b.length) {
        var ul = el('ul', 'cm-desc', null, d);
        c.b.forEach(function (line) {
          var li = el('li', line.indexOf('↳ ') === 0 ? 'sub' : '', line.replace(/^↳ /, ''), ul);
        });
      } else {
        el('p', 'cm-nodesc', '설명 없는 커밋 — 아래 변경 위치로 확인', d);
      }
      if (c.a.length) {
        el('div', 'cm-k', '주로 바뀐 곳', d);
        var grid = el('div', 'cm-areas', null, d);
        var max = Math.max.apply(null, c.a.map(function (a) { return a[1] + a[2]; })) || 1;
        c.a.forEach(function (a) {
          el('span', 'cm-area', a[0], grid);
          var bar = el('span', 'cm-bar', null, grid);
          var addBar = el('i', 'add', null, bar);
          var delBar = el('i', 'del', null, bar);
          addBar.style.width = (a[1] / max * 100) + '%';
          delBar.style.width = (a[2] / max * 100) + '%';
          el('span', 'cm-num mono', '+' + a[1] + ' −' + a[2], grid);
        });
      }
      var meta = el('div', 'cm-meta mono', null, d);
      el('span', '', '파일 ' + c.f + '개' + (c.x.length ? ' · ' + c.x.join(', ') : ''), meta);
      if (c.p === 0) {
        el('span', 'cm-local', '로컬 작업 브랜치 — 아직 GitHub에 없음', meta);
      } else {
        var a = el('a', 'cm-link', c.s + ' GitHub에서 보기 ↗', meta);
        a.href = REPO[rk].url + '/commit/' + c.s;
        a.target = '_blank';
        a.rel = 'noopener';
      }
      return d;
    }

    svg.addEventListener('click', function (ev) {
      var c = cellOf(ev.target);
      if (!c) { return; }
      var i = +c.getAttribute('data-i'), k = c.getAttribute('data-k');
      var n = +c.getAttribute('data-n');
      var monthTotal = sum(rows.map(function (r) { return r.counts[i]; }));
      if (!monthTotal) { return; }
      if (state && state.i === i && state.k === (n ? k : null)) { close(); return; }
      open(i, n ? (all ? k : key) : null);
    });

    // table view twin — month cells double as buttons into the same panel
    if (compact) { return; }
    var details = el('details', 'collapse', null, host);
    var summary = el('summary', '', '표로 보기 — 월별 커밋 수', details);
    el('span', 'count', '커밋이 있는 달만', summary);
    var wrap = el('div', 'tbl-wrap', null, details);
    var table = el('table', 'spec compact', null, wrap);
    var hr = el('tr', '', null, el('thead', '', null, table));
    el('th', '', '월', hr);
    rows.forEach(function (r) { el('th', 'num', r.name, hr); });
    if (all) { el('th', 'num', '합계', hr); }
    var tbody = el('tbody', '', null, table);
    for (var ti = 0; ti < COUNT; ti++) {
      var vals = rows.map(function (r) { return r.counts[ti]; });
      var rowSum = sum(vals);
      if (!rowSum) { continue; }
      var tr = el('tr', '', null, tbody);
      var td = el('td', 'mono', null, tr);
      var mb = el('button', 'hm-month', monthLabel(ti), td);
      mb.type = 'button';
      mb.addEventListener('click', (function (idx) { return function () { open(idx, all ? null : key); }; }(ti)));
      vals.forEach(function (v) { el('td', 'num mono', v ? String(v) : '·', tr); });
      if (all) { el('td', 'num mono', String(rowSum), tr); }
    }
  });
}());
